CREATE OR REPLACE FUNCTION public.srk_worker_record_session_location(
 p_session_id uuid,p_latitude double precision,p_longitude double precision,
 p_accuracy_m numeric DEFAULT NULL::numeric
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v_session public.srk_worker_work_sessions%rowtype;
 v_distance_m numeric;
 v_auto_resume_distance numeric;
 v_booking public.service_bookings%rowtype;
 v_auto_resumed boolean:=false;
 v_auto_paused boolean:=false;
 v_now timestamptz:=clock_timestamp();
 v_elapsed bigint;
begin
 if auth.uid() is null then raise exception 'Authentication required' using errcode='42501'; end if;
 if p_session_id is null or p_latitude is null or p_longitude is null
  or p_latitude not between -90 and 90 or p_longitude not between -180 and 180
  or (p_accuracy_m is not null and p_accuracy_m<0) then
  raise exception 'Valid GPS coordinates are required' using errcode='22023';
 end if;

 select s.* into v_session
 from public.srk_worker_work_sessions s
 join public.srk_booking_workers bw on bw.id=s.booking_worker_id
 join public.srk_worker_profiles wp on wp.id=bw.worker_id
 where s.id=p_session_id and wp.user_id=auth.uid()
 for update of s;
 if not found then raise exception 'Work session not found for this worker' using errcode='42501'; end if;

 select b.* into v_booking
 from public.service_bookings b
 join public.srk_booking_workers bw on bw.booking_id=b.id
 where bw.id=v_session.booking_worker_id;

 v_auto_resume_distance:=coalesce(
  (v_booking.operational_settings_snapshot->>'pause_auto_resume_distance_meters')::numeric,
  (select (setting_value #>> '{}')::numeric
   from public.srk_system_settings where setting_key='pause_auto_resume_distance_meters'),
  100
 );

 -- The first fresh GPS fix while running establishes the actual work-site anchor.
 update public.srk_worker_work_sessions
 set last_gps_latitude=p_latitude,last_gps_longitude=p_longitude,
     start_latitude=case when session_status='running' and start_latitude is null then p_latitude else start_latitude end,
     start_longitude=case when session_status='running' and start_longitude is null then p_longitude else start_longitude end,
     updated_at=v_now
 where id=p_session_id
 returning * into v_session;

 if v_session.start_latitude is not null and v_session.start_longitude is not null then
  v_distance_m:=6371000*2*asin(sqrt(
   power(sin(radians(p_latitude-v_session.start_latitude)/2),2)
   +cos(radians(v_session.start_latitude))*cos(radians(p_latitude))
   *power(sin(radians(p_longitude-v_session.start_longitude)/2),2)
  ));
 end if;

 -- Leaving the configured work-site radius automatically pauses billable time.
 if v_session.session_status='running'
    and v_session.start_latitude is not null
    and v_session.start_longitude is not null
    and v_distance_m>v_auto_resume_distance then
  v_elapsed:=greatest(0,floor(extract(epoch from(v_now-v_session.last_resumed_at)))::bigint);
  update public.srk_worker_work_sessions
  set session_status='paused',
      billable_seconds=least(5184000,billable_seconds+v_elapsed),
      last_resumed_at=null,pause_started_at=v_now,pause_minimum_until=v_now,
      pause_reason='gps_outside_worksite',updated_at=v_now
  where id=p_session_id returning * into v_session;
  update public.srk_booking_workers
  set assignment_status='paused',updated_at=v_now
  where id=v_session.booking_worker_id and assignment_status='working';
  insert into public.srk_worker_session_events(
   session_id,event_type,event_at,actor_user_id,pause_reason,note,source
  ) values(
   p_session_id,'paused',v_now,auth.uid(),'gps_outside_worksite',
   'Automatically paused because GPS moved outside the configured work-site radius.','system'
  );
  v_auto_paused:=true;

 elsif v_session.session_status='paused'
    and v_session.pause_reason='gps_outside_worksite'
    and v_session.pause_minimum_until is not null
    and v_now>=v_session.pause_minimum_until
    and v_session.start_latitude is not null
    and v_session.start_longitude is not null
    and v_distance_m<=v_auto_resume_distance then
  update public.srk_worker_work_sessions
  set session_status='running',last_resumed_at=v_now,pause_reason=null,
      pause_started_at=null,pause_minimum_until=null,updated_at=v_now
  where id=p_session_id returning * into v_session;
  update public.srk_booking_workers
  set assignment_status='working',updated_at=v_now
  where id=v_session.booking_worker_id and assignment_status='paused';
  insert into public.srk_worker_session_events(
   session_id,event_type,event_at,actor_user_id,pause_reason,note,source
  ) values(
   p_session_id,'resumed',v_now,auth.uid(),'gps_outside_worksite',
   'Automatically resumed after GPS returned within the configured work-site radius.','system'
  );
  v_auto_resumed:=true;
 end if;

 return jsonb_build_object(
  'success',true,'auto_paused',v_auto_paused,'auto_resumed',v_auto_resumed,
  'distance_from_start_m',v_distance_m,'worksite_radius_m',v_auto_resume_distance
 );
end
$function$;

alter table public.srk_worker_work_sessions
 add column if not exists last_gps_at timestamptz;

CREATE OR REPLACE FUNCTION public.srk_worker_session_action(
 p_session_id uuid,p_action text,p_pause_reason text DEFAULT NULL::text,
 p_note text DEFAULT NULL::text,p_idempotency_key text DEFAULT NULL::text
) RETURNS public.srk_worker_work_sessions
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v_session public.srk_worker_work_sessions%rowtype;
 v_existing_event public.srk_worker_session_events%rowtype;
 v_user_id uuid; v_booking_id uuid; v_now timestamptz:=clock_timestamp();
 v_elapsed bigint; v_booking public.service_bookings%rowtype; v_expected_event_type text;
 v_auto_resume_distance numeric; v_distance_m numeric;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 if p_idempotency_key is not null and
   (length(btrim(p_idempotency_key))=0 or length(p_idempotency_key)>200) then
   raise exception 'Invalid idempotency key' using errcode='22023';
 end if;
 select * into v_session from public.srk_worker_work_sessions where id=p_session_id for update;
 if not found then raise exception 'Work session not found'; end if;
 select wp.user_id,bw.booking_id into v_user_id,v_booking_id
 from public.srk_booking_workers bw join public.srk_worker_profiles wp on wp.id=bw.worker_id
 where bw.id=v_session.booking_worker_id;
 select * into v_booking from public.service_bookings where id=v_booking_id;
 if v_user_id is distinct from auth.uid() and not coalesce(public.is_srk_admin(),false) then
  raise exception 'Not authorized for this work session';
 end if;
 if p_idempotency_key is not null then
  v_expected_event_type:=case p_action when 'start' then 'started' when 'pause' then 'paused'
   when 'resume' then 'resumed' when 'complete' then 'completed' else null end;
  select * into v_existing_event from public.srk_worker_session_events
  where idempotency_key=p_idempotency_key for share;
  if found then
   if v_existing_event.session_id is distinct from p_session_id
    or v_existing_event.event_type is distinct from v_expected_event_type
    or v_existing_event.actor_user_id is distinct from auth.uid()
    or v_existing_event.pause_reason is distinct from p_pause_reason
    or v_existing_event.note is distinct from p_note
    or v_existing_event.source is distinct from 'app' then
    raise exception 'Idempotency key was already used for a different timer event' using errcode='22023';
   end if;
   return v_session;
  end if;
 end if;

 if p_action='start' then
  if v_session.session_status<>'not_started' then raise exception 'Session cannot be started from current state'; end if;
  if v_session.start_latitude is null or v_session.start_longitude is null
     or v_session.last_gps_latitude is null or v_session.last_gps_longitude is null
     or v_session.last_gps_at is null or v_session.last_gps_at<v_now-interval '2 minutes' then
   raise exception 'A fresh GPS location is required before starting the work timer';
  end if;
  update public.srk_worker_work_sessions
  set session_status='running',started_at=v_now,last_resumed_at=v_now,updated_at=v_now
  where id=p_session_id returning * into v_session;
  update public.srk_booking_workers set assignment_status='working',updated_at=v_now
   where id=v_session.booking_worker_id and assignment_status in ('accepted','assigned','paused');
  update public.service_bookings set status='in_progress',work_started_at=coalesce(work_started_at,v_now)
   where id=v_booking_id and status in ('new','confirmed','assigned','in_progress');
  insert into public.srk_worker_session_events(session_id,event_type,event_at,actor_user_id,note,idempotency_key)
   values(p_session_id,'started',v_now,auth.uid(),p_note,p_idempotency_key);

 elsif p_action='pause' then
  if v_session.session_status<>'running' then raise exception 'Only a running session can be paused'; end if;
  if p_pause_reason not in ('lunch','market_other') then raise exception 'Pause must be Lunch or Market/Other Task'; end if;
  v_elapsed:=greatest(0,floor(extract(epoch from(v_now-v_session.last_resumed_at)))::bigint);
  update public.srk_worker_work_sessions set session_status='paused',pause_started_at=v_now,
   pause_minimum_until=v_now+make_interval(mins=>case when p_pause_reason='lunch'
    then coalesce((v_booking.operational_settings_snapshot->>'lunch_pause_minimum_minutes')::integer,60)
    else coalesce((v_booking.operational_settings_snapshot->>'other_pause_minimum_minutes')::integer,120) end),
   billable_seconds=least(5184000,billable_seconds+v_elapsed),last_resumed_at=null,
   pause_reason=p_pause_reason,updated_at=v_now
  where id=p_session_id returning * into v_session;
  update public.srk_booking_workers set assignment_status='paused',updated_at=v_now where id=v_session.booking_worker_id;
  insert into public.srk_worker_session_events(session_id,event_type,event_at,actor_user_id,pause_reason,note,idempotency_key)
   values(p_session_id,'paused',v_now,auth.uid(),p_pause_reason,p_note,p_idempotency_key);

 elsif p_action='resume' then
  if v_session.session_status<>'paused' then raise exception 'Only a paused session can be resumed'; end if;
  if v_session.pause_minimum_until is not null and v_now<v_session.pause_minimum_until then
   raise exception 'Minimum pause duration has not elapsed';
  end if;
  if v_session.pause_reason='gps_outside_worksite' then
   if v_session.start_latitude is null or v_session.start_longitude is null
      or v_session.last_gps_latitude is null or v_session.last_gps_longitude is null
      or v_session.last_gps_at is null or v_session.last_gps_at<v_now-interval '2 minutes' then
    raise exception 'Fresh GPS location is required to resume inside the work-site radius';
   end if;
   v_auto_resume_distance:=coalesce(
    (v_booking.operational_settings_snapshot->>'pause_auto_resume_distance_meters')::numeric,
    (select (setting_value #>> '{}')::numeric from public.srk_system_settings where setting_key='pause_auto_resume_distance_meters'),100);
   v_distance_m:=6371000*2*asin(sqrt(
    power(sin(radians(v_session.last_gps_latitude-v_session.start_latitude)/2),2)
    +cos(radians(v_session.start_latitude))*cos(radians(v_session.last_gps_latitude))
    *power(sin(radians(v_session.last_gps_longitude-v_session.start_longitude)/2),2)
   ));
   if v_distance_m>v_auto_resume_distance then
    raise exception 'Cannot resume while outside the configured work-site radius';
   end if;
  end if;
  update public.srk_worker_work_sessions set session_status='running',last_resumed_at=v_now,pause_reason=null,
   pause_started_at=null,pause_minimum_until=null,updated_at=v_now
  where id=p_session_id returning * into v_session;
  update public.srk_booking_workers set assignment_status='working',updated_at=v_now where id=v_session.booking_worker_id;
  insert into public.srk_worker_session_events(session_id,event_type,event_at,actor_user_id,note,idempotency_key)
   values(p_session_id,'resumed',v_now,auth.uid(),p_note,p_idempotency_key);

 elsif p_action='complete' then
  if v_session.session_status not in ('running','paused') then raise exception 'Session cannot be completed from current state'; end if;
  v_elapsed:=case when v_session.session_status='running'
   then greatest(0,floor(extract(epoch from(v_now-v_session.last_resumed_at)))::bigint) else 0 end;
  update public.srk_worker_work_sessions set session_status='completed',
   billable_seconds=least(5184000,billable_seconds+v_elapsed),ended_at=v_now,last_resumed_at=null,
   completion_note=p_note,updated_at=v_now
  where id=p_session_id returning * into v_session;
  update public.srk_booking_workers set assignment_status='assigned',updated_at=v_now
   where id=v_session.booking_worker_id and assignment_status in ('working','paused');
  insert into public.srk_worker_session_events(session_id,event_type,event_at,actor_user_id,note,idempotency_key)
   values(p_session_id,'completed',v_now,auth.uid(),p_note,p_idempotency_key);
 else
  raise exception 'Unsupported session action';
 end if;
 return v_session;
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_worker_record_session_location(
 p_session_id uuid,p_latitude double precision,p_longitude double precision,
 p_accuracy_m numeric DEFAULT NULL::numeric
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v_session public.srk_worker_work_sessions%rowtype;
 v_distance_m numeric;
 v_auto_resume_distance numeric;
 v_booking public.service_bookings%rowtype;
 v_auto_resumed boolean:=false;
 v_auto_paused boolean:=false;
 v_now timestamptz:=clock_timestamp();
 v_elapsed bigint;
begin
 if auth.uid() is null then raise exception 'Authentication required' using errcode='42501'; end if;
 if p_session_id is null or p_latitude is null or p_longitude is null
  or p_latitude not between -90 and 90 or p_longitude not between -180 and 180
  or (p_accuracy_m is not null and p_accuracy_m<0) then
  raise exception 'Valid GPS coordinates are required' using errcode='22023';
 end if;
 select s.* into v_session
 from public.srk_worker_work_sessions s
 join public.srk_booking_workers bw on bw.id=s.booking_worker_id
 join public.srk_worker_profiles wp on wp.id=bw.worker_id
 where s.id=p_session_id and wp.user_id=auth.uid()
 for update of s;
 if not found then raise exception 'Work session not found for this worker' using errcode='42501'; end if;
 select b.* into v_booking from public.service_bookings b
 join public.srk_booking_workers bw on bw.booking_id=b.id
 where bw.id=v_session.booking_worker_id;
 v_auto_resume_distance:=coalesce(
  (v_booking.operational_settings_snapshot->>'pause_auto_resume_distance_meters')::numeric,
  (select (setting_value #>> '{}')::numeric from public.srk_system_settings where setting_key='pause_auto_resume_distance_meters'),100);

 update public.srk_worker_work_sessions
 set last_gps_latitude=p_latitude,last_gps_longitude=p_longitude,last_gps_at=v_now,
     start_latitude=case when session_status='not_started' then p_latitude
                         when session_status='running' and start_latitude is null then p_latitude
                         else start_latitude end,
     start_longitude=case when session_status='not_started' then p_longitude
                          when session_status='running' and start_longitude is null then p_longitude
                          else start_longitude end,
     updated_at=v_now
 where id=p_session_id returning * into v_session;

 if v_session.start_latitude is not null and v_session.start_longitude is not null then
  v_distance_m:=6371000*2*asin(sqrt(
   power(sin(radians(p_latitude-v_session.start_latitude)/2),2)
   +cos(radians(v_session.start_latitude))*cos(radians(p_latitude))
   *power(sin(radians(p_longitude-v_session.start_longitude)/2),2)
  ));
 end if;

 if v_session.session_status='running'
    and v_session.start_latitude is not null
    and v_session.start_longitude is not null
    and v_distance_m>v_auto_resume_distance then
  v_elapsed:=greatest(0,floor(extract(epoch from(v_now-v_session.last_resumed_at)))::bigint);
  update public.srk_worker_work_sessions
  set session_status='paused',billable_seconds=least(5184000,billable_seconds+v_elapsed),
      last_resumed_at=null,pause_started_at=v_now,pause_minimum_until=v_now,
      pause_reason='gps_outside_worksite',updated_at=v_now
  where id=p_session_id returning * into v_session;
  update public.srk_booking_workers set assignment_status='paused',updated_at=v_now
  where id=v_session.booking_worker_id and assignment_status='working';
  insert into public.srk_worker_session_events(session_id,event_type,event_at,actor_user_id,pause_reason,note,source)
  values(p_session_id,'paused',v_now,auth.uid(),'gps_outside_worksite',
   'Automatically paused because GPS moved outside the configured work-site radius.','system');
  v_auto_paused:=true;

 elsif v_session.session_status='paused'
    and v_session.pause_reason='gps_outside_worksite'
    and v_session.pause_minimum_until is not null
    and v_now>=v_session.pause_minimum_until
    and v_session.start_latitude is not null
    and v_session.start_longitude is not null
    and v_distance_m<=v_auto_resume_distance then
  update public.srk_worker_work_sessions
  set session_status='running',last_resumed_at=v_now,pause_reason=null,
      pause_started_at=null,pause_minimum_until=null,updated_at=v_now
  where id=p_session_id returning * into v_session;
  update public.srk_booking_workers set assignment_status='working',updated_at=v_now
  where id=v_session.booking_worker_id and assignment_status='paused';
  insert into public.srk_worker_session_events(session_id,event_type,event_at,actor_user_id,pause_reason,note,source)
  values(p_session_id,'resumed',v_now,auth.uid(),'gps_outside_worksite',
   'Automatically resumed after GPS returned within the configured work-site radius.','system');
  v_auto_resumed:=true;
 end if;

 return jsonb_build_object('success',true,'auto_paused',v_auto_paused,'auto_resumed',v_auto_resumed,
  'distance_from_start_m',v_distance_m,'worksite_radius_m',v_auto_resume_distance);
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_admin_override_work_timer(
 p_session_id uuid,p_timer_on boolean,p_reason text
) RETURNS public.srk_worker_work_sessions
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v_session public.srk_worker_work_sessions%rowtype;
 v_booking_id uuid; v_worker_id uuid; v_worker_user_id uuid; v_customer_user_id uuid;
 v_now timestamptz:=clock_timestamp(); v_elapsed bigint:=0; v_previous_status text;
begin
 if auth.uid() is null or not public.is_srk_admin() then
  raise exception 'Main Admin permission required' using errcode='42501';
 end if;
 if p_session_id is null or p_timer_on is null or length(btrim(coalesce(p_reason,'')))<10 then
  raise exception 'Session, timer action and a reason of at least 10 characters are required' using errcode='22023';
 end if;
 select * into v_session from public.srk_worker_work_sessions where id=p_session_id for update;
 if not found then raise exception 'Work session not found'; end if;
 v_previous_status:=v_session.session_status;
 select bw.booking_id,bw.worker_id,wp.user_id,b.customer_user_id
 into v_booking_id,v_worker_id,v_worker_user_id,v_customer_user_id
 from public.srk_booking_workers bw
 join public.srk_worker_profiles wp on wp.id=bw.worker_id
 join public.service_bookings b on b.id=bw.booking_id
 where bw.id=v_session.booking_worker_id;
 if not found then raise exception 'Booking worker assignment not found'; end if;

 if p_timer_on then
  if v_session.session_status not in ('not_started','paused') then
   raise exception 'Timer is already running or session is closed';
  end if;
  update public.srk_worker_work_sessions
  set session_status='running',started_at=coalesce(started_at,v_now),last_resumed_at=v_now,
      pause_reason=null,pause_started_at=null,pause_minimum_until=null,
      start_latitude=case when started_at is null then null else start_latitude end,
      start_longitude=case when started_at is null then null else start_longitude end,
      last_gps_latitude=null,last_gps_longitude=null,last_gps_at=null,updated_at=v_now
  where id=p_session_id returning * into v_session;
  update public.srk_booking_workers set assignment_status='working',updated_at=v_now
  where id=v_session.booking_worker_id;
  update public.service_bookings set status='in_progress',work_started_at=coalesce(work_started_at,v_now)
  where id=v_booking_id and status in ('new','confirmed','assigned','in_progress');
 else
  if v_session.session_status<>'running' then raise exception 'Only a running timer can be turned off'; end if;
  v_elapsed:=greatest(0,floor(extract(epoch from(v_now-v_session.last_resumed_at)))::bigint);
  update public.srk_worker_work_sessions
  set session_status='paused',billable_seconds=least(5184000,billable_seconds+v_elapsed),
      last_resumed_at=null,pause_reason=null,pause_started_at=v_now,pause_minimum_until=null,updated_at=v_now
  where id=p_session_id returning * into v_session;
  update public.srk_booking_workers set assignment_status='paused',updated_at=v_now
  where id=v_session.booking_worker_id;
 end if;

 insert into public.srk_worker_session_events(session_id,event_type,event_at,actor_user_id,note,source)
 values(p_session_id,'admin_adjusted',v_now,auth.uid(),
  case when p_timer_on then 'ADMIN TIMER ON: ' else 'ADMIN TIMER OFF: ' end||btrim(p_reason),'admin');
 insert into public.srk_admin_timer_override_events(
  session_id,booking_id,booking_worker_id,worker_id,admin_user_id,action,reason,previous_status,new_status
 ) values(p_session_id,v_booking_id,v_session.booking_worker_id,v_worker_id,auth.uid(),
  case when p_timer_on then 'timer_on' else 'timer_off' end,btrim(p_reason),
  v_previous_status,v_session.session_status);

 if v_customer_user_id is not null then
  insert into public.srk_app_notifications(user_id,notification_type,title,body,related_booking_id,deep_link)
  values(v_customer_user_id,'timer_admin_override','Work timer updated by Admin',
   case when p_timer_on then 'Admin ने कारण सहित काम का टाइमर चालू किया।' else 'Admin ने कारण सहित काम का टाइमर बंद किया।' end,
   v_booking_id,'/bookings/'||v_booking_id::text);
 end if;
 if v_worker_user_id is not null then
  insert into public.srk_app_notifications(user_id,notification_type,title,body,related_booking_id,deep_link)
  values(v_worker_user_id,'timer_admin_override','Work timer updated by Admin',
   case when p_timer_on then 'Admin ने कारण सहित आपका काम का टाइमर चालू किया।' else 'Admin ने कारण सहित आपका काम का टाइमर बंद किया।' end,
   v_booking_id,'/worker/bookings/'||v_booking_id::text);
 end if;
 return v_session;
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_worker_propose_next_schedule(
 p_booking_worker_id uuid,p_start_at timestamptz,p_end_at timestamptz
) RETURNS public.srk_booking_schedule_proposals
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v_proposal public.srk_booking_schedule_proposals%rowtype;
 v_booking_id uuid;
 v_assignment public.srk_booking_workers%rowtype;
 v_booking public.service_bookings%rowtype;
 v_old_proposal_id uuid;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 if p_booking_worker_id is null or p_start_at<=clock_timestamp() or p_end_at<=p_start_at then
  raise exception 'Future valid schedule range required';
 end if;

 select booking_id into v_booking_id
 from public.srk_booking_workers bw
 join public.srk_worker_profiles w on w.id=bw.worker_id
 where bw.id=p_booking_worker_id and w.user_id=auth.uid();
 if not found then raise exception 'Only assigned worker can propose the next work schedule'; end if;

 select * into v_booking from public.service_bookings
 where id=v_booking_id for update;
 if not found or v_booking.status='cancelled' or v_booking.status='completed' then
  raise exception 'Booking is no longer available for schedule proposals';
 end if;

 select * into v_assignment from public.srk_booking_workers
 where id=p_booking_worker_id for update;
 if not found or v_assignment.assignment_status not in ('accepted','assigned','working','paused') then
  raise exception 'Only an active assigned worker can propose the next work schedule';
 end if;

 -- Keep only one pending proposal per assignment. A newer proposal supersedes
 -- any unanswered proposal, while already accepted schedule blocks stay intact.
 for v_old_proposal_id in
  update public.srk_booking_schedule_proposals
  set status='cancelled',
      customer_response_note='Superseded by a newer worker schedule proposal.',
      responded_at=clock_timestamp()
  where booking_worker_id=p_booking_worker_id and status='proposed'
  returning id
 loop
  insert into public.srk_booking_schedule_events(proposal_id,actor_user_id,action,note,actor_type)
  values(v_old_proposal_id,auth.uid(),'cancelled','Superseded by a newer worker schedule proposal.','user');
 end loop;

 insert into public.srk_booking_schedule_proposals(
  booking_worker_id,proposed_by,proposed_start_at,proposed_end_at
 ) values(p_booking_worker_id,auth.uid(),p_start_at,p_end_at)
 returning * into v_proposal;

 insert into public.srk_booking_schedule_events(proposal_id,actor_user_id,action)
 values(v_proposal.id,auth.uid(),'proposed');
 return v_proposal;
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_worker_respond_assignment(p_assignment_id uuid,p_accept boolean)
RETURNS public.srk_booking_workers
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v_assignment public.srk_booking_workers%rowtype;
 v_worker public.srk_worker_profiles%rowtype;
 v_booking public.service_bookings%rowtype;
 v_accepted_count integer;
 v_requested_count integer;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;

 select bw.* into v_assignment
 from public.srk_booking_workers bw
 join public.srk_worker_profiles wp on wp.id=bw.worker_id
 where bw.id=p_assignment_id and wp.user_id=auth.uid()
 for update of bw;
 if not found or v_assignment.assignment_status<>'offered' then
  raise exception 'Offer not found or no longer pending';
 end if;
 if p_accept and v_assignment.offer_expires_at is not null
    and v_assignment.offer_expires_at<=clock_timestamp() then
  raise exception 'Offer has expired; wait for the next eligible assignment';
 end if;

 select * into v_booking from public.service_bookings
 where id=v_assignment.booking_id for update;
 if not found or v_booking.status='cancelled' then
  raise exception 'Booking is no longer available';
 end if;
 select * into v_worker from public.srk_worker_profiles
 where id=v_assignment.worker_id for update;
 if not found then raise exception 'Worker profile not found'; end if;

 if p_accept then
  if v_worker.verification_status<>'approved' or not v_worker.is_active then
   raise exception 'Worker is not currently approved and active';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(v_worker.id::text,0));

  if exists(select 1 from public.srk_worker_work_sessions s
            where s.worker_id=v_worker.id and s.session_status in ('running','paused'))
     or exists(select 1 from public.srk_booking_workers bw
               where bw.worker_id=v_worker.id and bw.assignment_status in ('working','paused')) then
   raise exception 'Finish or complete the active/paused booking before accepting another booking';
  end if;

  if exists(
   select 1 from public.srk_booking_workers bw
   where bw.worker_id=v_worker.id and bw.id<>v_assignment.id
    and bw.assignment_status in ('accepted','assigned')
    and not exists(
     select 1 from public.srk_worker_schedule_blocks sb
     where sb.booking_worker_id=bw.id
      and sb.block_status in ('reserved','confirmed','in_progress')
    )
  ) then
   raise exception 'Another accepted booking still needs a customer-confirmed schedule';
  end if;

  -- Revalidate the worker's current confirmed schedule while holding the same
  -- per-worker advisory lock used by schedule-block creation.
  if exists(
   select 1 from public.srk_worker_schedule_blocks sb
   where sb.worker_id=v_worker.id
    and sb.block_status in ('reserved','confirmed','in_progress')
    and sb.starts_at<=clock_timestamp()+make_interval(hours=>coalesce(v_booking.requested_duration_hours,1))
    and sb.ends_at>clock_timestamp()
  ) then
   raise exception 'A confirmed worker schedule conflicts with this booking';
  end if;

  v_requested_count:=case when v_assignment.worker_role='technician'
   then v_booking.requested_technician_count else v_booking.requested_helper_count end;
  select count(*) into v_accepted_count from public.srk_booking_workers
  where booking_id=v_assignment.booking_id and worker_role=v_assignment.worker_role
   and assignment_status in ('accepted','assigned','working','paused','completed');
  if v_accepted_count>=v_requested_count then
   raise exception 'Requested number of this worker role has already been filled';
  end if;
 end if;

 update public.srk_booking_workers
 set assignment_status=case when p_accept then 'accepted' else 'rejected' end,
     accepted_at=case when p_accept then clock_timestamp() else null end,
     rejected_at=case when p_accept then null else clock_timestamp() end,
     offer_expires_at=null,updated_at=clock_timestamp()
 where id=p_assignment_id returning * into v_assignment;

 if p_accept and v_assignment.worker_role='technician' then
  update public.service_bookings set status='confirmed'
  where id=v_assignment.booking_id and status='new';
 end if;
 update public.srk_booking_matching_queue
 set queue_status='pending',next_attempt_at=clock_timestamp(),updated_at=clock_timestamp()
 where booking_id=v_assignment.booking_id and queue_status not in ('fulfilled','cancelled');
 return v_assignment;
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_admin_release_booking_worker(p_assignment_id uuid,p_reason text)
RETURNS public.srk_booking_workers
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v public.srk_booking_workers%rowtype;
 v_session public.srk_worker_work_sessions%rowtype;
 v_now timestamptz:=clock_timestamp();
begin
 if not public.srk_has_admin_permission('bookings.manage') then
  raise exception 'Booking management permission required';
 end if;
 if p_assignment_id is null or length(btrim(coalesce(p_reason,'')))<10 then
  raise exception 'Release reason must be at least 10 characters';
 end if;

 select * into v from public.srk_booking_workers
 where id=p_assignment_id for update;
 if not found then raise exception 'Booking worker assignment not found'; end if;
 if v.assignment_status in ('completed','released','cancelled','rejected') then
  raise exception 'A completed or terminal assignment cannot be released again';
 end if;
 if exists(
  select 1 from public.srk_worker_work_sessions
  where booking_worker_id=p_assignment_id and session_status='running'
 ) then
  raise exception 'Pause or complete the active timer before releasing this worker';
 end if;

 -- Close paused/not-started daily sessions without losing their recorded billable seconds.
 for v_session in
  update public.srk_worker_work_sessions
  set session_status='cancelled',
      ended_at=coalesce(ended_at,v_now),
      last_resumed_at=null,
      pause_minimum_until=null,
      completion_note=coalesce(completion_note,'Admin released assignment: '||btrim(p_reason)),
      updated_at=v_now
  where booking_worker_id=p_assignment_id
    and session_status in ('not_started','paused')
  returning *
 loop
  insert into public.srk_worker_session_events(
   session_id,event_type,event_at,actor_user_id,pause_reason,note,source
  ) values(
   v_session.id,'cancelled',v_now,auth.uid(),v_session.pause_reason,
   'Admin closed this daily session while releasing the assignment: '||btrim(p_reason),
   'admin'
  );
 end loop;

 update public.srk_booking_workers
 set assignment_status='released',released_at=v_now,
     admin_note=btrim(p_reason),updated_at=v_now
 where id=p_assignment_id returning * into v;

 update public.srk_worker_schedule_blocks
 set block_status=case when ends_at<=v_now then 'completed' else 'cancelled' end,
     updated_at=v_now
 where booking_worker_id=p_assignment_id
   and block_status in ('reserved','confirmed','in_progress');

 update public.srk_booking_matching_queue
 set queue_status='pending',next_attempt_at=v_now,updated_at=v_now
 where booking_id=v.booking_id and queue_status<>'cancelled';

 insert into public.srk_app_notifications(user_id,notification_type,title,body,related_booking_id)
 select user_id,'assignment_released','Booking assignment updated',
  'Your assignment was released by Admin. Reason: '||btrim(p_reason),v.booking_id
 from public.srk_worker_profiles where id=v.worker_id;
 return v;
end
$function$;

create or replace function private.srk_cleanup_worker_schedule_after_assignment_terminal()
returns trigger
language plpgsql
security definer
set search_path to 'pg_catalog','public','auth'
as $function$
declare
 v_actor uuid:=auth.uid();
 v_proposal_id uuid;
 v_session record;
 v_note text;
 v_source text;
begin
 if tg_op='UPDATE'
    and new.assignment_status is distinct from old.assignment_status
    and new.assignment_status in ('completed','cancelled','released','rejected') then

  v_note:='Automatically closed because worker assignment status changed to '||new.assignment_status||'.';
  v_source:=case when v_actor is null then 'system' else 'user' end;

  -- Preserve billable seconds but close any daily session that never started
  -- or was paused when the assignment became terminal.
  for v_session in
   update public.srk_worker_work_sessions
   set session_status='cancelled',
       ended_at=coalesce(ended_at,clock_timestamp()),
       last_resumed_at=null,pause_minimum_until=null,
       completion_note=coalesce(completion_note,v_note),
       updated_at=clock_timestamp()
   where booking_worker_id=new.id and session_status in ('not_started','paused')
   returning id,pause_reason
  loop
   insert into public.srk_worker_session_events(
    session_id,event_type,event_at,actor_user_id,pause_reason,note,source
   ) values(
    v_session.id,'cancelled',clock_timestamp(),v_actor,v_session.pause_reason,v_note,v_source
   );
  end loop;

  update public.srk_worker_schedule_blocks
  set block_status=case when ends_at<=clock_timestamp() then 'completed' else 'cancelled' end,
      updated_at=clock_timestamp()
  where booking_worker_id=new.id
    and block_status in ('reserved','confirmed','in_progress');

  for v_proposal_id in
    update public.srk_booking_schedule_proposals
    set status='cancelled',customer_response_note=v_note,responded_at=clock_timestamp()
    where booking_worker_id=new.id and status in ('proposed','accepted')
    returning id
  loop
    insert into public.srk_booking_schedule_events(
      proposal_id,actor_user_id,action,note,actor_type
    ) values(
      v_proposal_id,v_actor,'cancelled',v_note,
      case when v_actor is null then 'system' else 'user' end
    );
  end loop;
 end if;
 return new;
end
$function$;

revoke all on function private.srk_cleanup_worker_schedule_after_assignment_terminal() from public,anon,authenticated;

CREATE OR REPLACE FUNCTION public.srk_worker_session_action(
 p_session_id uuid,p_action text,p_pause_reason text DEFAULT NULL::text,
 p_note text DEFAULT NULL::text,p_idempotency_key text DEFAULT NULL::text
) RETURNS public.srk_worker_work_sessions
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v_session public.srk_worker_work_sessions%rowtype;
 v_assignment public.srk_booking_workers%rowtype;
 v_existing_event public.srk_worker_session_events%rowtype;
 v_user_id uuid;
 v_booking_worker_id uuid;
 v_booking_id uuid;
 v_now timestamptz:=clock_timestamp();
 v_elapsed bigint;
 v_booking public.service_bookings%rowtype;
 v_expected_event_type text;
 v_auto_resume_distance numeric;
 v_distance_m numeric;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 if p_idempotency_key is not null and
   (length(btrim(p_idempotency_key))=0 or length(p_idempotency_key)>200) then
  raise exception 'Invalid idempotency key' using errcode='22023';
 end if;

 select booking_worker_id into v_booking_worker_id
 from public.srk_worker_work_sessions where id=p_session_id;
 if not found then raise exception 'Work session not found'; end if;
 select booking_id into v_booking_id
 from public.srk_booking_workers where id=v_booking_worker_id;
 if not found then raise exception 'Booking assignment not found'; end if;

 -- Global lock order: booking -> assignment -> work session.
 select * into v_booking from public.service_bookings where id=v_booking_id for update;
 if not found then raise exception 'Booking not found'; end if;
 select * into v_assignment from public.srk_booking_workers
 where id=v_booking_worker_id for update;
 if not found then raise exception 'Booking assignment not found'; end if;
 select * into v_session from public.srk_worker_work_sessions
 where id=p_session_id and booking_worker_id=v_assignment.id for update;
 if not found then raise exception 'Work session not found'; end if;

 select user_id into v_user_id from public.srk_worker_profiles where id=v_assignment.worker_id;
 if v_user_id is distinct from auth.uid() and not coalesce(public.is_srk_admin(),false) then
  raise exception 'Not authorized for this work session';
 end if;

 if p_idempotency_key is not null then
  v_expected_event_type:=case p_action when 'start' then 'started' when 'pause' then 'paused'
   when 'resume' then 'resumed' when 'complete' then 'completed' else null end;
  select * into v_existing_event from public.srk_worker_session_events
  where idempotency_key=p_idempotency_key for share;
  if found then
   if v_existing_event.session_id is distinct from p_session_id
    or v_existing_event.event_type is distinct from v_expected_event_type
    or v_existing_event.actor_user_id is distinct from auth.uid()
    or v_existing_event.pause_reason is distinct from p_pause_reason
    or v_existing_event.note is distinct from p_note
    or v_existing_event.source is distinct from 'app' then
    raise exception 'Idempotency key was already used for a different timer event' using errcode='22023';
   end if;
   return v_session;
  end if;
 end if;

 if p_action='start' then
  if v_session.session_status<>'not_started' then raise exception 'Session cannot be started from current state'; end if;
  if v_session.start_latitude is null or v_session.start_longitude is null
     or v_session.last_gps_latitude is null or v_session.last_gps_longitude is null
     or v_session.last_gps_at is null or v_session.last_gps_at<v_now-interval '2 minutes' then
   raise exception 'A fresh GPS location is required before starting the work timer';
  end if;
  update public.srk_worker_work_sessions
  set session_status='running',started_at=v_now,last_resumed_at=v_now,updated_at=v_now
  where id=p_session_id returning * into v_session;
  update public.srk_booking_workers set assignment_status='working',updated_at=v_now
  where id=v_assignment.id and assignment_status in ('accepted','assigned','paused');
  update public.service_bookings set status='in_progress',work_started_at=coalesce(work_started_at,v_now)
  where id=v_booking_id and status in ('new','confirmed','assigned','in_progress');
  insert into public.srk_worker_session_events(session_id,event_type,event_at,actor_user_id,note,idempotency_key)
  values(p_session_id,'started',v_now,auth.uid(),p_note,p_idempotency_key);

 elsif p_action='pause' then
  if v_session.session_status<>'running' then raise exception 'Only a running session can be paused'; end if;
  if p_pause_reason not in ('lunch','market_other') then raise exception 'Pause must be Lunch or Market/Other Task'; end if;
  v_elapsed:=greatest(0,floor(extract(epoch from(v_now-v_session.last_resumed_at)))::bigint);
  update public.srk_worker_work_sessions set session_status='paused',pause_started_at=v_now,
   pause_minimum_until=v_now+make_interval(mins=>case when p_pause_reason='lunch'
    then coalesce((v_booking.operational_settings_snapshot->>'lunch_pause_minimum_minutes')::integer,60)
    else coalesce((v_booking.operational_settings_snapshot->>'other_pause_minimum_minutes')::integer,120) end),
   billable_seconds=least(5184000,billable_seconds+v_elapsed),last_resumed_at=null,
   pause_reason=p_pause_reason,updated_at=v_now
  where id=p_session_id returning * into v_session;
  update public.srk_booking_workers set assignment_status='paused',updated_at=v_now where id=v_assignment.id;
  insert into public.srk_worker_session_events(session_id,event_type,event_at,actor_user_id,pause_reason,note,idempotency_key)
  values(p_session_id,'paused',v_now,auth.uid(),p_pause_reason,p_note,p_idempotency_key);

 elsif p_action='resume' then
  if v_session.session_status<>'paused' then raise exception 'Only a paused session can be resumed'; end if;
  if v_session.pause_minimum_until is not null and v_now<v_session.pause_minimum_until then
   raise exception 'Minimum pause duration has not elapsed';
  end if;
  if v_session.pause_reason='gps_outside_worksite' then
   if v_session.start_latitude is null or v_session.start_longitude is null
      or v_session.last_gps_latitude is null or v_session.last_gps_longitude is null
      or v_session.last_gps_at is null or v_session.last_gps_at<v_now-interval '2 minutes' then
    raise exception 'Fresh GPS location is required to resume inside the work-site radius';
   end if;
   v_auto_resume_distance:=coalesce(
    (v_booking.operational_settings_snapshot->>'pause_auto_resume_distance_meters')::numeric,
    (select (setting_value #>> '{}')::numeric from public.srk_system_settings where setting_key='pause_auto_resume_distance_meters'),100);
   v_distance_m:=6371000*2*asin(sqrt(
    power(sin(radians(v_session.last_gps_latitude-v_session.start_latitude)/2),2)
    +cos(radians(v_session.start_latitude))*cos(radians(v_session.last_gps_latitude))
    *power(sin(radians(v_session.last_gps_longitude-v_session.start_longitude)/2),2)
   ));
   if v_distance_m>v_auto_resume_distance then
    raise exception 'Cannot resume while outside the configured work-site radius';
   end if;
  end if;
  update public.srk_worker_work_sessions set session_status='running',last_resumed_at=v_now,pause_reason=null,
   pause_started_at=null,pause_minimum_until=null,updated_at=v_now
  where id=p_session_id returning * into v_session;
  update public.srk_booking_workers set assignment_status='working',updated_at=v_now where id=v_assignment.id;
  insert into public.srk_worker_session_events(session_id,event_type,event_at,actor_user_id,note,idempotency_key)
  values(p_session_id,'resumed',v_now,auth.uid(),p_note,p_idempotency_key);

 elsif p_action='complete' then
  if v_session.session_status not in ('running','paused') then raise exception 'Session cannot be completed from current state'; end if;
  v_elapsed:=case when v_session.session_status='running'
   then greatest(0,floor(extract(epoch from(v_now-v_session.last_resumed_at)))::bigint) else 0 end;
  update public.srk_worker_work_sessions set session_status='completed',
   billable_seconds=least(5184000,billable_seconds+v_elapsed),ended_at=v_now,last_resumed_at=null,
   completion_note=p_note,updated_at=v_now
  where id=p_session_id returning * into v_session;
  update public.srk_booking_workers set assignment_status='assigned',updated_at=v_now
  where id=v_assignment.id and assignment_status in ('working','paused');
  insert into public.srk_worker_session_events(session_id,event_type,event_at,actor_user_id,note,idempotency_key)
  values(p_session_id,'completed',v_now,auth.uid(),p_note,p_idempotency_key);
 else
  raise exception 'Unsupported session action';
 end if;
 return v_session;
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_worker_record_session_location(
 p_session_id uuid,p_latitude double precision,p_longitude double precision,
 p_accuracy_m numeric DEFAULT NULL::numeric
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v_session public.srk_worker_work_sessions%rowtype;
 v_assignment public.srk_booking_workers%rowtype;
 v_booking_worker_id uuid;
 v_worker_user_id uuid;
 v_distance_m numeric;
 v_auto_resume_distance numeric;
 v_booking public.service_bookings%rowtype;
 v_auto_resumed boolean:=false;
 v_auto_paused boolean:=false;
 v_now timestamptz:=clock_timestamp();
 v_elapsed bigint;
begin
 if auth.uid() is null then raise exception 'Authentication required' using errcode='42501'; end if;
 if p_session_id is null or p_latitude is null or p_longitude is null
  or p_latitude not between -90 and 90 or p_longitude not between -180 and 180
  or (p_accuracy_m is not null and p_accuracy_m<0) then
  raise exception 'Valid GPS coordinates are required' using errcode='22023';
 end if;

 select booking_worker_id into v_booking_worker_id
 from public.srk_worker_work_sessions where id=p_session_id;
 if not found then raise exception 'Work session not found' using errcode='42501'; end if;

 -- Assignment -> session lock order avoids deadlocks with booking cancellation/release.
 select * into v_assignment from public.srk_booking_workers
 where id=v_booking_worker_id for update;
 if not found then raise exception 'Booking assignment not found' using errcode='42501'; end if;
 select user_id into v_worker_user_id from public.srk_worker_profiles
 where id=v_assignment.worker_id;
 if v_worker_user_id is distinct from auth.uid() then
  raise exception 'Work session not found for this worker' using errcode='42501';
 end if;

 select * into v_session from public.srk_worker_work_sessions
 where id=p_session_id and booking_worker_id=v_assignment.id for update;
 if not found then raise exception 'Work session not found' using errcode='42501'; end if;

 select * into v_booking from public.service_bookings where id=v_assignment.booking_id;
 v_auto_resume_distance:=coalesce(
  (v_booking.operational_settings_snapshot->>'pause_auto_resume_distance_meters')::numeric,
  (select (setting_value #>> '{}')::numeric from public.srk_system_settings where setting_key='pause_auto_resume_distance_meters'),100);

 update public.srk_worker_work_sessions
 set last_gps_latitude=p_latitude,last_gps_longitude=p_longitude,last_gps_at=v_now,
     start_latitude=case when session_status='not_started' then p_latitude
                         when session_status='running' and start_latitude is null then p_latitude
                         else start_latitude end,
     start_longitude=case when session_status='not_started' then p_longitude
                          when session_status='running' and start_longitude is null then p_longitude
                          else start_longitude end,
     updated_at=v_now
 where id=p_session_id returning * into v_session;

 if v_session.start_latitude is not null and v_session.start_longitude is not null then
  v_distance_m:=6371000*2*asin(sqrt(
   power(sin(radians(p_latitude-v_session.start_latitude)/2),2)
   +cos(radians(v_session.start_latitude))*cos(radians(p_latitude))
   *power(sin(radians(p_longitude-v_session.start_longitude)/2),2)
  ));
 end if;

 if v_session.session_status='running'
    and v_session.start_latitude is not null
    and v_session.start_longitude is not null
    and v_distance_m>v_auto_resume_distance then
  v_elapsed:=greatest(0,floor(extract(epoch from(v_now-v_session.last_resumed_at)))::bigint);
  update public.srk_worker_work_sessions
  set session_status='paused',billable_seconds=least(5184000,billable_seconds+v_elapsed),
      last_resumed_at=null,pause_started_at=v_now,pause_minimum_until=v_now,
      pause_reason='gps_outside_worksite',updated_at=v_now
  where id=p_session_id returning * into v_session;
  update public.srk_booking_workers set assignment_status='paused',updated_at=v_now
  where id=v_assignment.id and assignment_status='working';
  insert into public.srk_worker_session_events(session_id,event_type,event_at,actor_user_id,pause_reason,note,source)
  values(p_session_id,'paused',v_now,auth.uid(),'gps_outside_worksite',
   'Automatically paused because GPS moved outside the configured work-site radius.','system');
  v_auto_paused:=true;

 elsif v_session.session_status='paused'
    and v_session.pause_reason='gps_outside_worksite'
    and v_session.pause_minimum_until is not null
    and v_now>=v_session.pause_minimum_until
    and v_session.start_latitude is not null
    and v_session.start_longitude is not null
    and v_distance_m<=v_auto_resume_distance then
  update public.srk_worker_work_sessions
  set session_status='running',last_resumed_at=v_now,pause_reason=null,
      pause_started_at=null,pause_minimum_until=null,updated_at=v_now
  where id=p_session_id returning * into v_session;
  update public.srk_booking_workers set assignment_status='working',updated_at=v_now
  where id=v_assignment.id and assignment_status='paused';
  insert into public.srk_worker_session_events(session_id,event_type,event_at,actor_user_id,pause_reason,note,source)
  values(p_session_id,'resumed',v_now,auth.uid(),'gps_outside_worksite',
   'Automatically resumed after GPS returned within the configured work-site radius.','system');
  v_auto_resumed:=true;
 end if;

 return jsonb_build_object('success',true,'auto_paused',v_auto_paused,'auto_resumed',v_auto_resumed,
  'distance_from_start_m',v_distance_m,'worksite_radius_m',v_auto_resume_distance);
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_worker_complete_assignment(
 p_booking_worker_id uuid,p_note text DEFAULT NULL::text
) RETURNS public.srk_booking_workers
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v_assignment public.srk_booking_workers%rowtype;
 v_booking public.service_bookings%rowtype;
 v_booking_id uuid;
 v_total_seconds bigint;
 v_remaining integer;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;

 select bw.booking_id into v_booking_id
 from public.srk_booking_workers bw
 join public.srk_worker_profiles wp on wp.id=bw.worker_id
 where bw.id=p_booking_worker_id and wp.user_id=auth.uid();
 if not found then raise exception 'Assignment not found or not yours'; end if;

 -- Keep the same booking -> assignment lock order as customer cancellation.
 select * into v_booking from public.service_bookings
 where id=v_booking_id for update;
 if not found then raise exception 'Booking not found'; end if;

 select bw.* into v_assignment
 from public.srk_booking_workers bw
 join public.srk_worker_profiles wp on wp.id=bw.worker_id
 where bw.id=p_booking_worker_id and wp.user_id=auth.uid()
 for update of bw;
 if not found then raise exception 'Assignment not found or not yours'; end if;

 if not exists(select 1 from public.srk_worker_work_sessions
  where booking_worker_id=p_booking_worker_id) then
  raise exception 'At least one work session is required';
 end if;
 if exists(select 1 from public.srk_worker_work_sessions
  where booking_worker_id=p_booking_worker_id
   and session_status not in ('completed','cancelled')) then
  raise exception 'Complete or cancel every daily work session first';
 end if;

 select coalesce(sum(billable_seconds),0) into v_total_seconds
 from public.srk_worker_work_sessions where booking_worker_id=p_booking_worker_id;
 if v_total_seconds<=0 then
  raise exception 'No billable work time recorded; Admin must release this assignment or arrange more work';
 end if;

 update public.srk_booking_workers
 set assignment_status='completed',released_at=clock_timestamp(),
     updated_at=clock_timestamp(),admin_note=coalesce(p_note,admin_note)
 where id=p_booking_worker_id and assignment_status<>'completed'
 returning * into v_assignment;
 if not found then raise exception 'Assignment is already completed or no longer active'; end if;

 select count(*) into v_remaining from public.srk_booking_workers
 where booking_id=v_assignment.booking_id
  and assignment_status not in ('completed','released','cancelled','rejected');
 if v_remaining=0 then
  update public.service_bookings
  set status='in_progress',completion_approval_status='pending',
      completion_requested_at=clock_timestamp(),work_timer_running=false
  where id=v_assignment.booking_id and status<>'completed';
 end if;
 return v_assignment;
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_worker_complete_assignment(
 p_booking_worker_id uuid,p_note text DEFAULT NULL::text
) RETURNS public.srk_booking_workers
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v_assignment public.srk_booking_workers%rowtype;
 v_booking public.service_bookings%rowtype;
 v_booking_id uuid;
 v_total_seconds bigint;
 v_remaining integer;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 select bw.booking_id into v_booking_id
 from public.srk_booking_workers bw
 join public.srk_worker_profiles wp on wp.id=bw.worker_id
 where bw.id=p_booking_worker_id and wp.user_id=auth.uid();
 if not found then raise exception 'Assignment not found or not yours'; end if;

 select * into v_booking from public.service_bookings
 where id=v_booking_id for update;
 if not found then raise exception 'Booking not found'; end if;

 select bw.* into v_assignment
 from public.srk_booking_workers bw
 join public.srk_worker_profiles wp on wp.id=bw.worker_id
 where bw.id=p_booking_worker_id and wp.user_id=auth.uid()
 for update of bw;
 if not found then raise exception 'Assignment not found or not yours'; end if;
 if v_assignment.assignment_status not in ('accepted','assigned','working','paused') then
  raise exception 'Assignment is not active and cannot be completed';
 end if;

 if not exists(select 1 from public.srk_worker_work_sessions where booking_worker_id=p_booking_worker_id) then
  raise exception 'At least one work session is required';
 end if;
 if exists(select 1 from public.srk_worker_work_sessions
  where booking_worker_id=p_booking_worker_id and session_status not in ('completed','cancelled')) then
  raise exception 'Complete or cancel every daily work session first';
 end if;
 select coalesce(sum(billable_seconds),0) into v_total_seconds
 from public.srk_worker_work_sessions where booking_worker_id=p_booking_worker_id;
 if v_total_seconds<=0 then
  raise exception 'No billable work time recorded; Admin must release this assignment or arrange more work';
 end if;

 update public.srk_booking_workers
 set assignment_status='completed',released_at=clock_timestamp(),
     updated_at=clock_timestamp(),admin_note=coalesce(p_note,admin_note)
 where id=p_booking_worker_id returning * into v_assignment;

 select count(*) into v_remaining from public.srk_booking_workers
 where booking_id=v_assignment.booking_id
  and assignment_status not in ('completed','released','cancelled','rejected');
 if v_remaining=0 then
  update public.service_bookings
  set status='in_progress',completion_approval_status='pending',
      completion_requested_at=clock_timestamp(),work_timer_running=false
  where id=v_booking.id and status<>'completed';
