CREATE OR REPLACE FUNCTION public.srk_worker_cancel_booking(p_booking_worker_id uuid,p_reason text)
RETURNS public.srk_booking_workers
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v_assignment public.srk_booking_workers%rowtype;
 v_booking public.service_bookings%rowtype;
 v_booking_id uuid;
 v_worker public.srk_worker_profiles%rowtype;
 v_customer_user_id uuid;
 v_remaining integer;
 v_requested integer;
 v_daily_count integer;
 v_request public.srk_worker_cancellation_approval_requests%rowtype;
 v_case public.srk_support_cases%rowtype;
begin
 if auth.uid() is null then raise exception 'Authentication required' using errcode='42501'; end if;
 if p_booking_worker_id is null or length(btrim(coalesce(p_reason,'')))<5 then
  raise exception 'Assignment and cancellation reason are required' using errcode='22023';
 end if;

 select bw.booking_id into v_booking_id
 from public.srk_booking_workers bw
 join public.srk_worker_profiles wp on wp.id=bw.worker_id
 where bw.id=p_booking_worker_id and wp.user_id=auth.uid();
 if not found then raise exception 'Booking assignment not found for this worker' using errcode='42501'; end if;

 -- Global lock order: booking -> assignment.
 select * into v_booking from public.service_bookings where id=v_booking_id for update;
 if not found then raise exception 'Booking not found'; end if;

 select bw.* into v_assignment
 from public.srk_booking_workers bw
 join public.srk_worker_profiles wp on wp.id=bw.worker_id
 where bw.id=p_booking_worker_id and wp.user_id=auth.uid()
 for update of bw;
 if not found then raise exception 'Booking assignment not found for this worker' using errcode='42501'; end if;
 if v_assignment.assignment_status not in ('offered','accepted','assigned') then
  raise exception 'This assignment cannot be cancelled directly; contact Support';
 end if;

 select * into v_worker from public.srk_worker_profiles where id=v_assignment.worker_id;
 if exists(
  select 1 from public.srk_worker_work_sessions s
  where s.booking_worker_id=v_assignment.id
   and (s.billable_seconds>0 or s.session_status in ('running','paused','completed'))
 ) then
  raise exception 'Work has started or timer evidence exists; contact Support for review';
 end if;

 select * into v_request from public.srk_worker_cancellation_approval_requests
 where booking_worker_id=v_assignment.id for update;
 if found and v_request.request_status='pending' then
  update public.srk_booking_workers set cancellation_request_status='pending',updated_at=clock_timestamp()
  where id=v_assignment.id returning * into v_assignment;
  return v_assignment;
 elsif found and v_request.request_status='rejected' then
  raise exception 'Admin rejected this cancellation request. Contact Support for help';
 elsif found and v_request.request_status='cancelled' then
  raise exception 'This cancellation request is no longer active';
 end if;

 if not (found and v_request.request_status='approved') then
  select count(*) into v_daily_count from public.srk_booking_cancellation_events e
  where e.actor_user_id=auth.uid() and e.actor_role=v_assignment.worker_role
   and (e.cancelled_at at time zone 'Asia/Kolkata')::date=(clock_timestamp() at time zone 'Asia/Kolkata')::date;
  if v_daily_count>=2 then
   insert into public.srk_support_cases(booking_id,raised_by,raised_by_role,category,subject,description,priority)
   values(v_booking.id,auth.uid(),v_assignment.worker_role,'worker_cancellation_approval',
    'Approval required for third daily cancellation',
    'Worker requested cancellation after reaching the daily limit of two. Reason: '||btrim(p_reason),'high')
   returning * into v_case;
   insert into public.srk_support_case_events(case_id,actor_user_id,action,new_status,note)
   values(v_case.id,auth.uid(),'worker_cancellation_approval_requested','open',p_reason);
   insert into public.srk_worker_cancellation_approval_requests(
    booking_worker_id,booking_id,worker_id,worker_user_id,worker_role,cancellation_reason,support_case_id
   ) values(v_assignment.id,v_booking.id,v_assignment.worker_id,auth.uid(),v_assignment.worker_role,p_reason,v_case.id)
   returning * into v_request;
   update public.srk_booking_workers set cancellation_request_status='pending',updated_at=clock_timestamp()
   where id=v_assignment.id returning * into v_assignment;
   insert into public.srk_app_notifications(user_id,notification_type,title,body,related_booking_id)
   select au.user_id,'worker_cancellation_approval','Worker cancellation approval required',
    'A '||v_assignment.worker_role||' has requested a third cancellation today. Please review support case '||
    coalesce(v_case.case_number,v_case.id::text)||'.',v_booking.id
   from public.srk_admin_users au;
   return v_assignment;
  end if;
 end if;

 update public.srk_booking_workers
 set assignment_status='cancelled',released_at=clock_timestamp(),
     cancellation_request_status=case when v_request.request_status='approved' then 'approved' else null end,
     admin_note='Worker cancellation: '||btrim(p_reason),updated_at=clock_timestamp()
 where id=v_assignment.id returning * into v_assignment;

 update public.srk_worker_schedule_blocks
 set block_status=case when ends_at<=clock_timestamp() then 'completed' else 'cancelled' end,
     updated_at=clock_timestamp()
 where booking_worker_id=v_assignment.id and block_status in ('reserved','confirmed','in_progress');

 select count(*) into v_remaining from public.srk_booking_workers
 where booking_id=v_booking.id and worker_role=v_assignment.worker_role
  and assignment_status in ('accepted','assigned','working','paused','completed');
 v_requested:=case when v_assignment.worker_role='technician'
  then v_booking.requested_technician_count else v_booking.requested_helper_count end;

 update public.srk_booking_no_show_reports
 set status='cancelled',resolved_at=clock_timestamp(),
     resolution_note='Worker assignment cancelled during no-show wait'
 where booking_worker_id=p_booking_worker_id and status='waiting';

 if v_remaining<v_requested then
  update public.srk_booking_matching_queue
  set queue_status='pending',next_attempt_at=clock_timestamp(),updated_at=clock_timestamp()
  where booking_id=v_booking.id and queue_status<>'cancelled';
  if v_assignment.worker_role='technician' and v_remaining=0 and v_booking.status in ('confirmed','assigned') then
   update public.service_bookings set status='new' where id=v_booking.id;
  end if;
 end if;

 insert into public.srk_booking_cancellation_events(booking_id,actor_user_id,actor_role,reason)
 values(v_booking.id,auth.uid(),v_assignment.worker_role,p_reason);
 if v_request.request_status='approved' then
  update public.srk_worker_cancellation_approval_requests
  set completed_at=clock_timestamp() where id=v_request.id;
 end if;

 select customer_user_id into v_customer_user_id from public.service_bookings where id=v_booking.id;
 if v_customer_user_id is not null then
  insert into public.srk_app_notifications(user_id,notification_type,title,body,related_booking_id,deep_link)
  values(v_customer_user_id,'worker_assignment_cancelled','Worker assignment cancelled',
   'A '||v_assignment.worker_role||' cancelled their assignment. SRK ELECTRONIC is searching for a replacement. Reason: '||btrim(p_reason),
   v_booking.id,'/bookings/'||v_booking.id::text);
 end if;
 insert into public.srk_app_notifications(user_id,notification_type,title,body,related_booking_id,deep_link)
 select au.user_id,'worker_assignment_cancelled','Worker cancelled an assignment',
  'Worker '||v_worker.worker_code||' cancelled booking '||coalesce(v_booking.order_number,v_booking.id::text)||
  '. Reason: '||btrim(p_reason),v_booking.id,'/admin/bookings/'||v_booking.id::text
 from public.srk_admin_users au;
 return v_assignment;
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_process_booking_matching_queue()
RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public'
AS $function$
declare
 v_queue_candidate record;
 v_queue record;
 v_booking public.service_bookings%rowtype;
 v_timeout integer;
 v_max_attempts integer;
 v_default_timeout integer;
 v_default_max_attempts integer;
 v_tech_count integer;
 v_helper_count integer;
 v_tech_offered integer;
 v_helper_offered integer;
 v_candidate record;
 v_level uuid;
 v_rate_id uuid;
 v_rate numeric(10,2);
 v_role text;
 v_inserted integer:=0;
 v_offered boolean;
 v_rule public.srk_service_pricing_rules%rowtype;
begin
 select nullif(setting_value::text,'null')::integer into v_timeout
 from public.srk_system_settings where setting_key='offer_timeout_seconds';
 v_default_timeout:=v_timeout;
 select coalesce(nullif(setting_value::text,'null')::integer,10) into v_max_attempts
 from public.srk_system_settings where setting_key='max_matching_attempts';
 v_max_attempts:=coalesce(v_max_attempts,10);
 v_default_max_attempts:=v_max_attempts;

 if v_timeout is not null then
  update public.srk_booking_workers
  set assignment_status='rejected',rejected_at=clock_timestamp(),
      admin_note='Offer timed out',updated_at=clock_timestamp()
  where assignment_status='offered' and offer_expires_at is not null
    and offer_expires_at<=clock_timestamp();
 end if;

 -- Read candidate IDs without locking the queue. Lock order is booking -> queue
 -- so customer/worker actions can safely update the queue while holding booking.
 for v_queue_candidate in
  select q.booking_id from public.srk_booking_matching_queue q
  where q.queue_status in ('pending','searching','waiting')
    and q.next_attempt_at<=clock_timestamp()
  order by q.created_at limit 25
 loop
  select * into v_booking from public.service_bookings
  where id=v_queue_candidate.booking_id for update skip locked;
  if not found then continue; end if;

  select * into v_queue from public.srk_booking_matching_queue q
  where q.booking_id=v_queue_candidate.booking_id
    and q.queue_status in ('pending','searching','waiting')
    and q.next_attempt_at<=clock_timestamp()
  for update skip locked;
  if not found then continue; end if;

  v_timeout:=coalesce((v_booking.operational_settings_snapshot->>'offer_timeout_seconds')::integer,v_default_timeout);
  v_max_attempts:=coalesce((v_booking.operational_settings_snapshot->>'max_matching_attempts')::integer,v_default_max_attempts);

  if v_booking.status='cancelled' then
   update public.srk_booking_matching_queue set queue_status='cancelled',updated_at=clock_timestamp()
   where booking_id=v_queue_candidate.booking_id;
   continue;
  end if;

  select count(*) into v_tech_count from public.srk_booking_workers
  where booking_id=v_booking.id and worker_role='technician'
   and assignment_status in ('accepted','assigned','working','paused','completed');
  select count(*) into v_helper_count from public.srk_booking_workers
  where booking_id=v_booking.id and worker_role='helper'
   and assignment_status in ('accepted','assigned','working','paused','completed');
  select count(*) into v_tech_offered from public.srk_booking_workers
  where booking_id=v_booking.id and worker_role='technician' and assignment_status='offered';
  select count(*) into v_helper_offered from public.srk_booking_workers
  where booking_id=v_booking.id and worker_role='helper' and assignment_status='offered';

  if v_tech_count>=1 then
   update public.service_bookings set status='confirmed' where id=v_booking.id and status='new';
  end if;

  if v_tech_count>=v_booking.requested_technician_count
     and v_helper_count>=v_booking.requested_helper_count then
   update public.srk_booking_workers set assignment_status='assigned',updated_at=clock_timestamp()
   where booking_id=v_booking.id and assignment_status='accepted';
   update public.srk_booking_matching_queue
   set queue_status='fulfilled',completed_at=coalesce(completed_at,clock_timestamp()),updated_at=clock_timestamp()
   where booking_id=v_booking.id;
   update public.service_bookings set status='confirmed' where id=v_booking.id and status='new';
   continue;
  end if;

  v_role:=case when v_tech_count<v_booking.requested_technician_count then 'technician' else 'helper' end;
  if (v_role='technician' and v_tech_offered>0) or (v_role='helper' and v_helper_offered>0) then
   update public.srk_booking_matching_queue
   set queue_status='searching',next_attempt_at=clock_timestamp()+interval '1 minute',updated_at=clock_timestamp()
   where booking_id=v_booking.id;
   continue;
  end if;

  if coalesce(v_queue.attempts,0)>=v_max_attempts then
   update public.srk_booking_matching_queue
   set queue_status='failed',
       last_error='Maximum matching attempts ('||v_max_attempts||') reached; required worker role remains unfilled.',
       next_attempt_at=clock_timestamp(),updated_at=clock_timestamp()
   where booking_id=v_booking.id;
   continue;
  end if;

  select * into v_rule from public.srk_service_pricing_rules where id=v_booking.pricing_rule_id;
  v_offered:=false;
  for v_candidate in
   select c.* from public.srk_find_eligible_workers(v_booking.id,v_role) c
   where not exists(
    select 1 from public.srk_booking_workers bw
    where bw.booking_id=v_booking.id and bw.worker_id=c.worker_id
   )
   order by c.distance_km
  loop
   select ws.skill_level_id into v_level from public.srk_worker_skills ws
   where ws.worker_id=v_candidate.worker_id and ws.skill_id=v_booking.selected_skill_id
     and ws.verification_status='approved' limit 1;
   v_rate_id:=null; v_rate:=null;

   if v_booking.pricing_unit_snapshot='motor_hp' then
    if v_rule.id is null or v_rule.pricing_unit<>'motor_hp'
       or not exists(select 1 from public.srk_service_pricing_hp_tiers t
        where t.pricing_rule_id=v_rule.id and t.motor_hp=v_booking.motor_hp) then
     continue;
    end if;
    v_rate:=null;
   elsif v_booking.pricing_unit_snapshot='per_item' then
    if v_rule.id is null or v_rule.pricing_unit<>'per_item' then continue; end if;
    if v_role='technician' then v_rate:=v_rule.technician_rate; else v_rate:=v_rule.helper_rate; end if;
    if v_role='technician' and (v_rate is null or v_rate<=0) then continue; end if;
   else
    if v_booking.pricing_rule_id is not null and v_rule.pricing_unit='hour' then
     if v_role='technician' then v_rate:=v_rule.technician_rate; else v_rate:=v_rule.helper_rate; end if;
     if v_rate is null then continue; end if;
    else
     select r.id,case when v_role='technician' then r.technician_hourly_rate else r.helper_hourly_rate end
      into v_rate_id,v_rate
     from public.srk_service_rates r
     where r.category_id=v_booking.category_id and r.skill_level_id=v_level
       and (r.service_type_id is null or r.service_type_id=v_booking.service_type_id)
       and r.rate_status='approved' and r.effective_from<=clock_timestamp()
       and (r.effective_to is null or r.effective_to>clock_timestamp())
       and (case when v_role='technician' then r.technician_hourly_rate else r.helper_hourly_rate end) is not null
     order by (r.service_type_id is not null) desc,r.effective_from desc limit 1;
     if v_rate is null then continue; end if;
    end if;
   end if;

   insert into public.srk_booking_workers(
    booking_id,worker_id,worker_role,assignment_status,rate_id,hourly_rate_snapshot,
    skill_level_snapshot_id,offer_expires_at,worker_custom_settings_snapshot
   ) values(
    v_booking.id,v_candidate.worker_id,v_role,'offered',v_rate_id,
    case when v_booking.pricing_unit_snapshot in ('per_item','motor_hp') then null else v_rate end,
    v_level,
    case when v_timeout is null then null else clock_timestamp()+make_interval(secs=>v_timeout) end,
    coalesce((select jsonb_object_agg(setting_key,setting_value)
      from public.srk_user_custom_settings
      where user_id=(select user_id from public.srk_worker_profiles where id=v_candidate.worker_id)
       and account_role=v_role),'{}'::jsonb)
   );
   v_inserted:=v_inserted+1;
   v_offered:=true;
  end loop;

  if v_offered then
   update public.srk_booking_matching_queue
   set queue_status='searching',attempts=attempts+1,last_attempt_at=clock_timestamp(),
       next_attempt_at=clock_timestamp()+make_interval(secs=>coalesce(v_timeout,600)),
       last_error=null,updated_at=clock_timestamp()
   where booking_id=v_booking.id;
  else
   update public.srk_booking_matching_queue
   set queue_status='waiting',attempts=attempts+1,last_attempt_at=clock_timestamp(),
       next_attempt_at=clock_timestamp()+interval '1 minute',
       last_error='No eligible online approved worker with an approved pricing rule/rate',
       updated_at=clock_timestamp()
   where booking_id=v_booking.id;
  end if;
 end loop;
 return v_inserted;
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_worker_respond_assignment(p_assignment_id uuid,p_accept boolean)
RETURNS public.srk_booking_workers
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v_assignment public.srk_booking_workers%rowtype;
 v_worker public.srk_worker_profiles%rowtype;
 v_booking public.service_bookings%rowtype;
 v_booking_id uuid;
 v_worker_id uuid;
 v_accepted_count integer;
 v_requested_count integer;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;

 select bw.booking_id,bw.worker_id into v_booking_id,v_worker_id
 from public.srk_booking_workers bw
 join public.srk_worker_profiles wp on wp.id=bw.worker_id
 where bw.id=p_assignment_id and wp.user_id=auth.uid();
 if not found then raise exception 'Offer not found or not yours'; end if;

 -- Global lock order: booking -> assignment -> worker.
 select * into v_booking from public.service_bookings
 where id=v_booking_id for update;
 if not found or v_booking.status='cancelled' then
  raise exception 'Booking is no longer available';
 end if;

 select bw.* into v_assignment
 from public.srk_booking_workers bw
 join public.srk_worker_profiles wp on wp.id=bw.worker_id
 where bw.id=p_assignment_id and wp.user_id=auth.uid()
 for update of bw;
 if not found or v_assignment.assignment_status<>'offered' then
  raise exception 'Offer not found or no longer pending';
 end if;

 if p_accept and v_assignment.offer_expires_at is not null
    and v_assignment.offer_expires_at<=clock_timestamp() then
  raise exception 'Offer has expired; wait for the next eligible assignment';
 end if;

 select * into v_worker from public.srk_worker_profiles
 where id=v_worker_id for update;
 if not found then raise exception 'Worker profile not found'; end if;

 if p_accept then
  if v_worker.verification_status<>'approved' or not v_worker.is_active then
   raise exception 'Worker is not currently approved and active';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(v_worker.id::text,0));

  if exists(select 1 from public.srk_worker_work_sessions s
            where s.worker_id=v_worker.id and s.session_status in ('running','paused'))
     or exists(select 1 from public.srk_booking_workers bw
               where bw.worker_id=v_worker.id and bw.assignment_status in ('working','paused')) then
   raise exception 'Finish or complete the active/paused booking before accepting another booking';
  end if;

  if exists(
   select 1 from public.srk_booking_workers bw
   where bw.worker_id=v_worker.id and bw.id<>v_assignment.id
    and bw.assignment_status in ('accepted','assigned')
    and not exists(
     select 1 from public.srk_worker_schedule_blocks sb
     where sb.booking_worker_id=bw.id and sb.block_status in ('reserved','confirmed','in_progress')
    )
  ) then
   raise exception 'Another accepted booking still needs a customer-confirmed schedule';
  end if;

  if exists(
   select 1 from public.srk_worker_schedule_blocks sb
   where sb.worker_id=v_worker.id and sb.block_status in ('reserved','confirmed','in_progress')
    and sb.starts_at<=clock_timestamp()+make_interval(hours=>coalesce(v_booking.requested_duration_hours,1))
    and sb.ends_at>clock_timestamp()
  ) then
   raise exception 'A confirmed worker schedule conflicts with this booking';
  end if;

  v_requested_count:=case when v_assignment.worker_role='technician'
   then v_booking.requested_technician_count else v_booking.requested_helper_count end;
  select count(*) into v_accepted_count from public.srk_booking_workers
  where booking_id=v_assignment.booking_id and worker_role=v_assignment.worker_role
   and assignment_status in ('accepted','assigned','working','paused','completed');
  if v_accepted_count>=v_requested_count then
   raise exception 'Requested number of this worker role has already been filled';
  end if;
 end if;

 update public.srk_booking_workers
 set assignment_status=case when p_accept then 'accepted' else 'rejected' end,
     accepted_at=case when p_accept then clock_timestamp() else null end,
     rejected_at=case when p_accept then null else clock_timestamp() end,
     offer_expires_at=null,updated_at=clock_timestamp()
 where id=p_assignment_id returning * into v_assignment;

 if p_accept and v_assignment.worker_role='technician' then
  update public.service_bookings set status='confirmed'
  where id=v_assignment.booking_id and status='new';
 end if;
 update public.srk_booking_matching_queue
 set queue_status='pending',next_attempt_at=clock_timestamp(),updated_at=clock_timestamp()
 where booking_id=v_assignment.booking_id and queue_status not in ('fulfilled','cancelled');
 return v_assignment;
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_process_no_show_reports()
RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public'
AS $function$
declare
 v_candidate record;
 v_report public.srk_booking_no_show_reports%rowtype;
 v_booking public.service_bookings%rowtype;
 v_customer uuid;
 v_count integer:=0;
begin
 -- Lock order is booking -> no-show report -> assignments/queue.
 for v_candidate in
  select r.id,r.booking_id
  from public.srk_booking_no_show_reports r
  where r.status='waiting' and r.review_due_at<=clock_timestamp()
  order by r.review_due_at limit 100
 loop
  select * into v_booking from public.service_bookings
  where id=v_candidate.booking_id for update skip locked;
  if not found then continue; end if;

  select * into v_report from public.srk_booking_no_show_reports
  where id=v_candidate.id and status='waiting' and review_due_at<=clock_timestamp()
  for update skip locked;
  if not found then continue; end if;

  if v_booking.status in ('completed','cancelled') then
   update public.srk_booking_no_show_reports
   set status='resolved',resolved_at=clock_timestamp(),
       resolution_note='Booking was already closed before the no-show processor ran.'
   where id=v_report.id;
   v_count:=v_count+1;
   continue;
  end if;

  if exists(
   select 1 from public.srk_booking_workers bw
   where bw.id=v_report.booking_worker_id and bw.arrived_at is not null
  ) then
   update public.srk_booking_no_show_reports
   set status='resolved',resolved_at=clock_timestamp(),
       resolution_note='Worker arrived during the 10-minute waiting window'
   where id=v_report.id;
  else
   update public.srk_booking_no_show_reports
   set status='cancelled',admin_notified_at=clock_timestamp(),resolved_at=clock_timestamp(),
       resolution_note='No-show confirmed after the 10-minute wait; cancelled without fee'
   where id=v_report.id;

   update public.service_bookings
   set status='cancelled',
       admin_change_reason='No-show auto-cancellation after 10-minute wait; no cancellation fee'
   where id=v_booking.id and status not in ('completed','cancelled');

   update public.srk_booking_matching_queue
   set queue_status='cancelled',updated_at=clock_timestamp()
   where booking_id=v_booking.id;

   update public.srk_booking_workers
   set assignment_status='cancelled',
       admin_note='No-show auto-cancellation after 10-minute wait',
       updated_at=clock_timestamp()
   where booking_id=v_booking.id
     and assignment_status in ('offered','accepted','assigned','working','paused');

   update public.srk_worker_schedule_blocks
   set block_status=case when ends_at<=clock_timestamp() then 'completed' else 'cancelled' end,
       updated_at=clock_timestamp()
   where booking_worker_id in(
    select id from public.srk_booking_workers where booking_id=v_booking.id
   ) and block_status in ('reserved','confirmed','in_progress');

   update public.srk_booking_location_shares
   set ended_at=clock_timestamp()
   where booking_id=v_booking.id and ended_at is null;

   update public.srk_booking_cancellation_fees
   set status='pending',next_booking_id=null,added_to_next_booking_at=null
   where next_booking_id=v_booking.id and status='added_to_next_booking';
   update public.service_bookings set pending_cancellation_fee_amount=0 where id=v_booking.id;

   v_customer:=v_booking.customer_user_id;
   if v_customer is not null then
    insert into public.srk_app_notifications(user_id,notification_type,title,body,related_booking_id)
    values(v_customer,'booking_no_show_cancelled','Booking cancelled due to no-show',
     '10-minute waiting period ended. Booking cancelled without any cancellation fee.',v_booking.id);
   end if;
   insert into public.srk_app_notifications(user_id,notification_type,title,body,related_booking_id)
   select au.user_id,'booking_no_show_cancelled','No-show booking auto-cancelled',
    'Booking '||v_booking.id::text||' cancelled after 10-minute wait. No fee charged.',v_booking.id
   from public.srk_admin_users au;
  end if;
  v_count:=v_count+1;
 end loop;
 return v_count;
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_admin_settle_cash_worker_share(
 p_earning_id uuid,p_actual_cash_share numeric,p_reason text
) RETURNS public.srk_worker_earnings
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v public.srk_worker_earnings%rowtype;
 v_booking public.service_bookings%rowtype;
 v_booking_id uuid;
 v_worker_id uuid;
 v_service_total numeric(12,2);
 v_already_allocated numeric(12,2);
 v_commission numeric(12,2);
 v_existing_due numeric(12,2);
 v_fixed_allocation numeric(12,2);
begin
 if auth.uid() is null or not public.srk_has_admin_permission('payouts.manage') then
  raise exception 'Payout management permission required' using errcode='42501';
 end if;
 if p_earning_id is null or p_actual_cash_share is null
    or p_actual_cash_share<0 or p_actual_cash_share<>round(p_actual_cash_share,2)
    or p_reason is null or length(btrim(p_reason)) not between 10 and 2000 then
  raise exception 'Valid earning, non-negative two-decimal cash share and 10-2000 character reason are required'
   using errcode='22023';
 end if;

 select worker_id,booking_id into v_worker_id,v_booking_id
 from public.srk_worker_earnings where id=p_earning_id;
 if not found then raise exception 'Worker earning not found'; end if;

 -- Global financial lock order: booking -> worker -> earning.
 select * into v_booking from public.service_bookings where id=v_booking_id for update;
 if not found then raise exception 'Booking not found'; end if;
 perform 1 from public.srk_worker_profiles where id=v_worker_id for update;
 if not found then raise exception 'Worker profile not found'; end if;
 select * into v from public.srk_worker_earnings
 where id=p_earning_id for update;
 if not found or v.worker_id<>v_worker_id or v.payment_method<>'cash'
    or v.settlement_status<>'cash_split_pending' then
  raise exception 'Cash earning is not awaiting split settlement';
 end if;
 if v_booking.payment_status<>'paid' then
  raise exception 'Cash payment must be confirmed before settlement';
 end if;

 select f.service_amount into v_service_total
 from public.srk_booking_final_bills f
 where f.id=v.bill_id and f.booking_id=v.booking_id;
 if v_service_total is null then raise exception 'Final bill labour amount not found'; end if;

 if v_booking.pricing_unit_snapshot in ('per_item','motor_hp') then
  select a.gross_service_earning into v_fixed_allocation
  from public.srk_fixed_price_worker_allocations a
  where a.booking_id=v_booking_id and a.booking_worker_id=v.booking_worker_id
    and a.worker_id=v.worker_id for share;
  if not found then raise exception 'Approved fixed-price worker allocation is missing'; end if;
  if p_actual_cash_share is distinct from v_fixed_allocation then
   raise exception 'Cash share must match the approved fixed-price worker allocation';
  end if;
 end if;

 select coalesce(sum(e.gross_service_earning),0) into v_already_allocated
 from public.srk_worker_earnings e
 where e.booking_id=v_booking_id and e.payment_method='cash' and e.id<>v.id
  and exists(select 1 from public.srk_worker_wallet_ledger l
   where l.earning_id=e.id and l.entry_type='cash_commission_due');
 if v_already_allocated+p_actual_cash_share>v_service_total then
  raise exception 'Cash shares exceed total labour amount';
 end if;
 if v.company_commission_rate is null or v.company_commission_rate<0 or v.company_commission_rate>100 then
  raise exception 'Earning commission snapshot is invalid';
 end if;

 v_commission:=round(p_actual_cash_share*v.company_commission_rate/100,2);
 select amount into v_existing_due from public.srk_worker_wallet_ledger
 where idempotency_key='cash-share-commission:'||v.id::text;
 if found and v_existing_due<>v_commission then
  raise exception 'Existing cash commission ledger amount differs; reconciliation required';
 end if;

 update public.srk_worker_earnings
 set gross_service_earning=p_actual_cash_share,company_commission=v_commission,
     net_earning=p_actual_cash_share-v_commission,settlement_status='cash_commission_due',
     payout_status='pending',admin_note=btrim(p_reason),updated_at=clock_timestamp()
 where id=p_earning_id returning * into v;

 insert into public.srk_worker_wallet_ledger(
  worker_id,booking_id,earning_id,entry_type,amount,balance_effect,description,idempotency_key
 ) values(
  v.worker_id,v.booking_id,v.id,'cash_commission_due',v_commission,-v_commission,
  'Admin-settled cash share commission: '||btrim(p_reason),
  'cash-share-commission:'||v.id::text
 ) on conflict(idempotency_key) do nothing;
 return v;
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_on_booking_payment_completed()
RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v_bw record;
 v_count bigint;
 v_next bigint;
 v_method text;
 v_normalized_method text;
 v_payment_done boolean;
begin
 v_payment_done:=new.status='completed'
  and lower(coalesce(new.payment_status,'')) in ('paid','completed');
 v_method:=lower(coalesce(new.payment_method,''));
 v_normalized_method:=case when v_method in ('upi','card','online') then 'online'
  when v_method='cash' then 'cash' else null end;

 if new.status='completed' and old.status is distinct from 'completed' then
  for v_bw in
   select bw.worker_id
   from public.srk_booking_workers bw
   join public.srk_worker_profiles wp on wp.id=bw.worker_id
   where bw.booking_id=new.id and bw.worker_role='technician'
    and wp.worker_type='technician'
    and (
     bw.assignment_status='completed'
     or (bw.assignment_status='released' and exists(
       select 1 from public.srk_worker_work_sessions s
       where s.booking_worker_id=bw.id and s.billable_seconds>0
     ))
    )
   order by bw.worker_id
  loop
   if exists(select 1 from public.srk_technician_booking_sequence s
    where s.technician_id=v_bw.worker_id and s.booking_id=new.id) then
    continue;
   end if;
   insert into public.srk_technician_booking_cycle(technician_id)
   values(v_bw.worker_id) on conflict(technician_id) do nothing;
   select completed_booking_count into v_count
   from public.srk_technician_booking_cycle
   where technician_id=v_bw.worker_id for update;
   v_next:=v_count+1;
   if mod(v_next,3)=0 and v_payment_done and v_normalized_method<>'online' then
    raise exception 'Technician completed booking number % must be paid online',v_next;
   end if;
   update public.srk_technician_booking_cycle
   set completed_booking_count=v_next,last_completed_at=clock_timestamp(),updated_at=clock_timestamp()
   where technician_id=v_bw.worker_id;
   insert into public.srk_technician_booking_sequence(technician_id,booking_id,sequence_number,payment_method)
   values(v_bw.worker_id,new.id,v_next,case when v_payment_done then v_normalized_method else null end);
  end loop;

  -- Helpers have their own independent 1-6 payment sequence.
  for v_bw in
   select bw.worker_id
   from public.srk_booking_workers bw
   join public.srk_worker_profiles wp on wp.id=bw.worker_id
   where bw.booking_id=new.id and bw.worker_role='helper'
    and wp.worker_type='helper'
    and (
     bw.assignment_status='completed'
     or (bw.assignment_status='released' and exists(
       select 1 from public.srk_worker_work_sessions s
       where s.booking_worker_id=bw.id and s.billable_seconds>0
     ))
    )
   order by bw.worker_id
  loop
   if exists(select 1 from public.srk_helper_booking_sequence s
    where s.helper_id=v_bw.worker_id and s.booking_id=new.id) then
    continue;
   end if;
   insert into public.srk_helper_booking_cycle(helper_id)
   values(v_bw.worker_id) on conflict(helper_id) do nothing;
   select completed_booking_count into v_count
   from public.srk_helper_booking_cycle
   where helper_id=v_bw.worker_id for update;
   v_next:=v_count+1;
   if mod(v_next,3)=0 and v_payment_done and v_normalized_method<>'online' then
    raise exception 'Helper completed booking number % must be paid online',v_next;
   end if;
   update public.srk_helper_booking_cycle
   set completed_booking_count=v_next,last_completed_at=clock_timestamp(),updated_at=clock_timestamp()
   where helper_id=v_bw.worker_id;
   insert into public.srk_helper_booking_sequence(helper_id,booking_id,sequence_number,payment_method)
   values(v_bw.worker_id,new.id,v_next,case when v_payment_done then v_normalized_method else null end);
  end loop;
 end if;

 if v_payment_done
    and not (old.status='completed' and lower(coalesce(old.payment_status,'')) in ('paid','completed')) then
  if v_normalized_method is null then
   raise exception 'A valid payment method is required before marking payment completed';
  end if;
  if exists(select 1 from public.srk_technician_booking_sequence s
   where s.booking_id=new.id and mod(s.sequence_number,3)=0 and v_normalized_method<>'online') then
   raise exception 'Technician booking number 3 or 6 must be paid online';
  end if;
  if exists(select 1 from public.srk_helper_booking_sequence s
   where s.booking_id=new.id and mod(s.sequence_number,3)=0 and v_normalized_method<>'online') then
   raise exception 'Helper booking number 3 or 6 must be paid online';
  end if;

  update public.srk_technician_booking_sequence set payment_method=v_normalized_method where booking_id=new.id;
  update public.srk_helper_booking_sequence set payment_method=v_normalized_method where booking_id=new.id;
  update public.srk_worker_earnings set payment_method=v_normalized_method,updated_at=clock_timestamp()
  where booking_id=new.id;
  perform public.srk_post_one_worker_earning(e.id)
  from public.srk_worker_earnings e where e.booking_id=new.id;
 end if;

 if v_payment_done then
  update public.srk_booking_cancellation_fees
  set status='paid',paid_at=clock_timestamp()
  where next_booking_id=new.id and status='added_to_next_booking';
 end if;
 return new;
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_admin_review_worker_payout(
 p_payout_id uuid,p_approve boolean,p_approved_amount numeric DEFAULT NULL::numeric,p_note text DEFAULT NULL::text
) RETURNS public.srk_worker_payout_requests
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v_payout public.srk_worker_payout_requests%rowtype;
 v_worker public.srk_worker_profiles%rowtype;
 v_available numeric(12,2);
 v_reserved numeric(12,2);
 v_amount numeric(12,2);
begin
 if auth.uid() is null or not public.srk_has_admin_permission('payouts.manage') then
  raise exception 'Payout management permission required' using errcode='42501';
 end if;
 if p_approve is null then raise exception 'Approval decision is required' using errcode='22023'; end if;
 if p_approved_amount is not null and
  (p_approved_amount<=0 or p_approved_amount<>round(p_approved_amount,2)) then
  raise exception 'Approved amount must be positive and limited to two decimal places' using errcode='22023';
 end if;

 select * into v_payout from public.srk_worker_payout_requests
 where id=p_payout_id for update;
 if not found or v_payout.status not in ('requested','under_review') then
  raise exception 'Payout request not reviewable';
 end if;

 select * into v_worker from public.srk_worker_profiles
 where id=v_payout.worker_id for update;
 if not found then raise exception 'Worker profile not found'; end if;

 if exists(select 1 from public.srk_worker_earnings
  where worker_id=v_payout.worker_id and settlement_status='held') then
  raise exception 'Worker payout is held due to refund/dispute review';
 end if;

 if not p_approve then
  update public.srk_worker_payout_requests
  set status='rejected',reviewed_at=clock_timestamp(),reviewed_by=auth.uid(),admin_note=p_note
  where id=p_payout_id returning * into v_payout;
  return v_payout;
 end if;

 if v_worker.payout_details_change_status<>'approved'
    or v_worker.payout_details_reviewed_by is null
    or v_worker.payout_details_reviewed_at is null
    or (nullif(btrim(v_worker.upi_id),'') is null
        and nullif(btrim(v_worker.bank_account_last4),'') is null) then
  raise exception 'Worker must submit payout details and receive Main Admin verification before payout approval';
 end if;

 v_amount:=coalesce(p_approved_amount,v_payout.requested_amount);
 select coalesce(sum(balance_effect),0) into v_available
 from public.srk_worker_wallet_ledger where worker_id=v_payout.worker_id;
 select coalesce(sum(coalesce(approved_amount,requested_amount)),0) into v_reserved
 from public.srk_worker_payout_requests
 where worker_id=v_payout.worker_id and id<>p_payout_id
  and status in ('requested','under_review','approved');
 if v_amount<=0 or v_amount>v_payout.requested_amount or v_amount>v_available-v_reserved then
  raise exception 'Approved amount exceeds unreserved available balance';
 end if;

 update public.srk_worker_payout_requests
 set status='approved',approved_amount=v_amount,reviewed_at=clock_timestamp(),
     reviewed_by=auth.uid(),admin_note=p_note
 where id=p_payout_id returning * into v_payout;
 return v_payout;
end
$function$;

alter table public.srk_worker_work_sessions
 add constraint srk_worker_sessions_last_gps_timestamp_pair_check
 check ((last_gps_latitude is null)=(last_gps_at is null));
